/**
 * Message Display Observer
 * Hook: MessageDisplay (CC 2.1.152)
 *
 * Fires as assistant message text is displayed. The event CAN rewrite or
 * hide the text (via `hookSpecificOutput.displayContent`, the only key CC
 * reads here per spec/cc-output-keys.spec.yml). This hook is an OBSERVER
 * ONLY: it never blocks and never returns displayContent, so displayed
 * prose passes through byte-for-byte unchanged.
 *
 * HISTORY. A P3-A3 observer for this event was written and reverted on
 * 2026-07-15 because `claude plugin validate` rejected `hooks.MessageDisplay`
 * as "Invalid key in record". Re-verified on CC 2.1.226 (#3327): the
 * validator DOES still inspect hooks/hooks.json and DOES still reject
 * unknown event keys — a probe with a fabricated `TotallyBogusEventZZZ`
 * key failed with exactly that error — but it now ACCEPTS both
 * MessageDisplay and DirectoryAdded. The block is gone.
 *
 * MessageDisplay is high-frequency (once per assistant message delta), so
 * the handler stays allocation-light and logs metrics only. Message content
 * is NEVER logged — it may carry secrets — only length metrics.
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, logHook } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';

const HOOK_NAME = 'notification/message-display-observer';

/** Candidate keys for the displayed text across plausible payload shapes. */
const TEXT_KEYS = ['content', 'message', 'text', 'delta', 'display_content'] as const;

/** Length of the first readable text field; -1 when none is present. */
function displayedLength(input: HookInput): number {
  const rec = input as unknown as Record<string, unknown>;
  for (const key of TEXT_KEYS) {
    const v = rec[key];
    if (typeof v === 'string') return v.length;
  }
  return -1;
}

export async function messageDisplayObserver(
  input: HookInput,
  _ctx: HookContext = NOOP_CTX,
): Promise<HookResult> {
  try {
    const len = displayedLength(input);
    logHook(
      HOOK_NAME,
      `message displayed len=${len < 0 ? '(unreadable)' : len}`,
      'info',
    );
  } catch {
    // Observer only — never let telemetry failures surface to CC
  }
  return outputSilentSuccess();
}
